mapper.select:
select tran.* from Tran tran,issue_info io where tran.cusip=io.cusip  and io.securityid=#{secid}
and tran.portfolio in

	#{item}

order by id desc

choose.otherwise:

        	select * from Tran where ledger_Date>#{startDate} and ledger_Date<=#{endDate} 
        	and portfolio in
			<foreach item="item" collection="portList" index="index" open="(" separator="," close=")">
				#{item}
			</foreach>
			and cusip is not null order by id asc

mapper.select:

			select tran.* from Tran tran, Issue_Info ii where tran.cusip=ii.cusip and ii.issueType=#{assetType} and tran.portfolio=#{portnum} 
        	and greatest(tran.settle_Date,tran.ledger_Date)>#{startDate} and greatest(tran.settle_Date,tran.ledger_Date)<=#{endDate}  
        	order by tran.id asc
